import itertools

def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def get_bk(s, n, k):
    return {t for t in itertools.product('01', repeat=n) if hamming_distance(s, t) == k}

def check_uniqueness(n, k):
    s_sets = {}
    all_strings = list(itertools.product('01', repeat=n))
    for s in all_strings:
        bk = tuple(sorted(get_bk(s, n, k)))
        if bk not in s_sets:
            s_sets[bk] = []
        s_sets[bk].append(s)

    max_guesses = 0
    for bk in s_sets:
        max_guesses = max(max_guesses, len(s_sets[bk]))
    return max_guesses

for k in range(1, 3):
    for n in range(2*k + 1, 2*k + 4):
        print(f"n={n}, k={k}, max_guesses={check_uniqueness(n, k)}")

